import{n as e}from"./flux-rolldown-runtime-WkwZ5CU-.js";import{A as t,i as n,j as r,l as i,s as a}from"./flux-context-lKZiv7O7.js";import{t as o}from"./flux-client-Cn_G1bdZ.js";import{t as s}from"./flux-useTranslation-R9PbT6VH.js";import{S as c,gt as l,vt as u}from"./flux-modules-DdhibDIU.js";import{a as d,i as f,n as p,s as m,t as h}from"./flux-react-CAXVyiAK.js";import{A as g,B as _,C as v,D as y,E as b,F as x,G as S,H as C,I as ee,J as w,K as T,L as E,M as te,N as ne,O as D,P as O,R as k,S as re,T as ie,U as ae,V as oe,W as se,X as ce,Y as A,Z as le,_ as j,b as ue,c as de,d as fe,f as M,g as N,h as pe,j as me,k as he,l as ge,m as _e,p as P,q as ve,u as ye,v as be,w as xe,x as Se,y as F,z as Ce}from"./flux-operations-B3mdtCqA.js";var I=e(r(),1),we={en:{},tr:{"The action could not be completed.":`İşlem tamamlanamadı.`,"Try again":`Tekrar dene`,Report:`Rapor`,Campaigns:`Kampanyalar`,Suggestions:`Öneriler`,Studio:`Stüdyo`,"Season plan":`Sezon planı`,Tests:`Testler`,"Donor value":`Bağışçı değeri`,"Ad spend":`Reklam harcaması`,Audiences:`Kitleler`,"Send log":`Gönderim kaydı`,"Ad link":`Reklam bağlantısı`,Settings:`Ayarlar`,"Ad conversions":`Reklam dönüşümleri`,"Classic view":`Klasik görünüm`,"Which ad, campaign and ad text brought which donation. Paid donations and orders only; bank transfers count when approved.":`Hangi reklam, kampanya ve reklam metni hangi bağışı getirdi. Yalnız ödenmiş bağış ve siparişler; Havale/EFT onaylanınca sayılır.`,Close:`Kapat`,Cancel:`Vazgeç`,"Checked: %d new suggestion.\0Checked: %d new suggestions.":`Kontrol edildi: %d yeni öneri.\0Kontrol edildi: %d yeni öneri.`,Spend:`Harcama`,Impressions:`Gösterim`,"Link clicks":`Bağlantı tıklaması`,"%s%% CTR":`%s%% TO`,"Status changed in Meta.":`Durum Meta'da değişti.`,"Daily budget changed in Meta.":`Günlük bütçe Meta'da değişti.`,'"%s" stops showing in Meta right away. You can turn it back on any time.':`"%s" Meta'da hemen durur. İstediğiniz zaman yeniden açabilirsiniz.`,'"%s" starts showing in Meta and spending its budget.':`"%s" Meta'da yayınlanmaya ve bütçesini harcamaya başlar.`,Pause:`Duraklat`,"Turn on":`Aç`,'The daily budget of "%1$s" changes in Meta right away (now %2$s).':`"%1$s" günlük bütçesi Meta'da hemen değişir (şu an %2$s).`,"Change budget":`Bütçeyi değiştir`,"Daily budget":`Günlük bütçe`,Save:`Kaydet`,"Your Meta campaigns, ad sets and ads with spend and the donations they brought on this site. Pause, turn on or change the daily budget here; every change goes to Meta at once and is written to the change history.":`Meta kampanyaların, reklam setlerin ve reklamların; harcamaları ve bu sitede getirdikleri bağışlarla. Günlük bütçeyi buradan durdur, aç ya da değiştir; her değişiklik hemen Meta'ya gider ve değişiklik geçmişine yazılır.`,Period:`Dönem`,"Meta could not be read:":`Meta okunamadı:`,"Brought on the site":`Sitede getirdiği`,"%s payments":`%s ödeme`,"Return on ad spend (ROAS)":`Reklam getirisi (ROAS)`,"Active campaigns":`Etkin kampanya`,"%s in total":`toplam %s`,Campaign:`Kampanya`,Budget:`Bütçe`,"On the site":`Sitede`,"No campaigns in this ad account.":`Bu reklam hesabında kampanya yok.`,"in ad sets":`reklam setlerinde`,"Donations on the site are matched by campaign name or ID in the ad link (utm_campaign). Meta numbers are refreshed every 10 minutes.":`Sitedeki bağışlar reklam bağlantısındaki kampanya adı ya da kimliğiyle (utm_campaign) eşleşir. Meta rakamları 10 dakikada bir yenilenir.`,"All campaigns":`Tüm kampanyalar`,"Ad sets and ads":`Reklam setleri ve reklamlar`,"Ad set / ad":`Reklam seti / reklam`,"No ad sets.":`Reklam seti yok.`,"Ad set":`Reklam seti`,Ad:`Reklam`,"Age and gender":`Yaş ve cinsiyet`,Placement:`Yerleşim`,"No data for this period.":`Bu dönem için veri yok.`,"Change history":`Değişiklik geçmişi`,When:`Ne zaman`,What:`Ne`,Change:`Değişiklik`,Who:`Kim`,"Applied in Meta and written to the change history.":`Meta'da uygulandı ve değişiklik geçmişine yazıldı.`,"Dismissed. It does not come back for 14 days.":`Kapatıldı. 14 gün boyunca yeniden gelmez.`,"Flux Ads checks your active Meta campaigns every day against what they brought on this site, and suggests what to change. Nothing changes until you press Apply; every change goes to the change history under Campaigns.":`Flux Ads etkin Meta kampanyalarınızı her gün sitede getirdikleriyle karşılaştırır ve neyin değişmesi gerektiğini önerir. Uygula'ya basmadıkça hiçbir şey değişmez; her değişiklik Kampanyalar'daki değişiklik geçmişine yazılır.`,"Last check %s.":`Son kontrol %s.`,"Change the rules":`Kuralları değiştir`,"Check now":`Şimdi kontrol et`,"No suggestions now. Your active campaigns are within the target.":`Şu an öneri yok. Etkin kampanyalarınız hedef içinde.`,Apply:`Uygula`,"Write a draft":`Taslak yaz`,"Open Studio":`Stüdyo'yu aç`,Dismiss:`Kapat`,"Earlier suggestions":`Önceki öneriler`,Suggestion:`Öneri`,Result:`Sonuç`,"Test saved.":`Test kaydedildi.`,"Test deleted.":`Test silindi.`,"Find out what really works. A/B: two ads in the same campaign, compared by donations per click on this site. Holdout: a fixed share of an audience does not see the ads; comparing the two groups shows how many donations the ads really added.":`Gerçekte neyin işe yaradığını öğrenin. A/B: aynı kampanyadaki iki reklam, bu sitede tıklama başına bağışla karşılaştırılır. Holdout: kitlenin sabit bir payı reklamı görmez; iki grubu karşılaştırmak reklamların gerçekte kaç bağış eklediğini gösterir.`,"No tests yet.":`Henüz test yok.`,Running:`Sürüyor`,Ended:`Bitti`,'Pause "%s" in Meta?':`"%s" Meta'da duraklatılsın mı?`,'Pause "%s"':`"%s" reklamını duraklat`,"End the test? The held-out people go back into the Meta audience.":`Test bitsin mi? Dışarıda tutulan kişiler Meta kitlesine geri girer.`,"End the test? The result is kept.":`Test bitsin mi? Sonuç saklanır.`,"End test":`Testi bitir`,"Delete this test and its result?":`Bu test ve sonucu silinsin mi?`,Delete:`Sil`,"New A/B test":`Yeni A/B testi`,"No active campaign with ads. Create two variants in Studio first.":`Reklamlı etkin kampanya yok. Önce Stüdyo'da iki çeşit oluşturun.`,"Pick two ads of the same campaign. Studio drafts already tag each variant (utm_content), so donations are counted per ad.":`Aynı kampanyadan iki reklam seçin. Stüdyo taslakları her çeşidi zaten etiketler (utm_content); bağışlar reklam başına sayılır.`,"Ad A":`Reklam A`,"Ad B":`Reklam B`,Start:`Başlangıç`,End:`Bitiş`,"Start test":`Testi başlat`,"New holdout test":`Yeni holdout testi`,"Create a Meta audience that ads are shown to (Audiences) first. An audience runs one holdout test at a time.":`Önce reklam gösterilen bir Meta kitlesi oluşturun (Kitleler). Bir kitlede aynı anda tek holdout testi çalışır.`,"The held-out people are removed from the Meta audience right away and put back when the test ends. Run it for at least 4 weeks; the bigger the audience, the sooner the answer.":`Dışarıda tutulan kişiler Meta kitlesinden hemen çıkar, test bitince geri girer. En az 4 hafta çalıştırın; kitle ne kadar büyükse cevap o kadar erken gelir.`,"Start the test? The held-out people are removed from the Meta audience now.":`Test başlasın mı? Dışarıda tutulan kişiler Meta kitlesinden şimdi çıkarılır.`,Audience:`Kitle`,"Held out (%)":`Dışarıda tutulan (%)`,"Enter the Meta ad account ID and a Marketing API key in Settings › Meta. Reading needs ads_read; pausing and budget changes need ads_management.":`Ayarlar › Meta'ya reklam hesabı kimliğini ve Marketing API anahtarını girin. Okumak için ads_read, duraklatma ve bütçe değişikliği için ads_management izni gerekir.`,"%s group\0%s groups":`%s grup\0%s grup`,"Clear filter":`Filtreyi kaldır`,"Brought by ads":`Reklamların getirdiği`,"%s%% of all income":`tüm gelirin %%%s'i`,"Payments from ads":`Reklamdan gelen ödeme`,"of %s in total":`toplam %s ödemeden`,"Total income":`Toplam gelir`,"New donors and customers":`Yeni bağışçı ve müşteri`,"first paid order":`ilk ödemesini yapan`,"%s link clicks":`%s bağlantı tıklaması`,"%s income from these ads":`Bu reklamlardan %s gelir`,"Cost per payment":`Ödeme başı maliyet`,"Cost per new donor":`Yeni bağışçı başı maliyet`,"%s new":`%s yeni`,"Some payments are in another currency and no exchange rate was found; their amount is shown per currency in the row but not added to the totals. Install Flux CRM for currency conversion.":`Bazı ödemeler başka para biriminde ve kur bulunamadı; tutarları satırda para birimine göre görünür ama toplama eklenmez. Kur çevirisi için Flux CRM'i kurun.`,Payments:`Ödeme`,Amount:`Tutar`,New:`Yeni`,Share:`Pay`,"No paid donation or order in this period yet. Use the Ad link tab to tag your ads.":`Bu dönemde henüz ödenmiş bağış ya da sipariş yok. Reklamlarınızı etiketlemek için Reklam bağlantısı sekmesini kullanın.`,"%s per payment":`ödeme başı %s`,"Latest payments from ads":`Reklamdan gelen son ödemeler`,Date:`Tarih`,Order:`Sipariş`,"None yet.":`Henüz yok.`,Donation:`Bağış`,new:`yeni`,"Meta spend updated.":`Meta harcaması güncellendi.`,"Spend added.":`Harcama eklendi.`,"Spend deleted.":`Harcama silindi.`,"Meta ad spend":`Meta reklam harcaması`,"Update now":`Şimdi güncelle`,"Enter the ad account ID in Settings › Meta. Spend per campaign and ad is then read every 6 hours, so the report shows ROAS and cost per donation.":`Ayarlar › Meta'da reklam hesabı kimliğini girin. Kampanya ve reklam bazında harcama 6 saatte bir okunur; rapor ROAS'ı ve bağış başı maliyeti gösterir.`,"Not read yet. It runs in the background after this page loads; refresh in a minute.":`Henüz okunmadı. Bu sayfa yüklendikten sonra arka planda çalışır; bir dakika sonra yenileyin.`,"Updated %1$s: %2$s – %3$s, %4$d rows. Updates every 6 hours.":`%1$s güncellendi: %2$s – %3$s, %4$d satır. 6 saatte bir güncellenir.`,"Last update failed:":`Son güncelleme başarısız:`,"The key needs the ads_read permission on this ad account: Business Settings › Users › System users › add the ad account › Generate token (ads_read).":`Anahtarın bu reklam hesabında ads_read izni olmalı: İşletme Ayarları › Kullanıcılar › Sistem kullanıcıları › reklam hesabını ekleyin › Anahtar oluştur (ads_read).`,Channel:`Kanal`,"No spend in this period.":`Bu dönemde harcama yok.`,Total:`Toplam`,"Spend is matched to donations by campaign name (utm_campaign) and ad name (utm_content). Use the Meta URL parameters from the Ad link tab so the names are the same.":`Harcama bağışlarla kampanya adı (utm_campaign) ve reklam adı (utm_content) üzerinden eşleşir. Adlar aynı olsun diye Reklam bağlantısı sekmesindeki Meta URL parametrelerini kullanın.`,"Add spend by hand":`Harcamayı elle ekle`,"For Google Ads, TikTok, posters or anything not read automatically. Use the same campaign name as in the ad link.":`Google Ads, TikTok, afiş ya da otomatik okunmayan her şey için. Reklam bağlantısındaki kampanya adının aynısını yazın.`,"Ad (optional)":`Reklam (isteğe bağlı)`,Currency:`Para birimi`,"Add spend":`Harcama ekle`,"What the people an ad brought in gave in total, not only their first payment. A campaign whose first gifts are cheap but never come back shows up here.":`Reklamın getirdiği kişilerin yalnız ilk ödemesi değil, toplamda verdiği. İlk bağışı ucuza getirip bir daha dönmeyen kampanya burada görünür.`,"First payment in":`İlk ödeme`,"%s of them from ads":`%s tanesi reklamdan`,"Value per person from ads":`Reklamdan gelen kişi başı değer`,"all payments so far":`bugüne kadarki tüm ödemeler`,"Cost to win one (CAC)":`Bir kişiyi kazanma maliyeti (CAC)`,"%s spend":`%s harcama`,"no spend recorded":`harcama kaydı yok`,"Value / cost":`Değer / maliyet`,"%s%% gave again":`%%%s tekrar verdi`,"First payment":`İlk ödeme`,"90 days":`90 gün`,"So far":`Bugüne kadar`,"Per person":`Kişi başı`,"Gave again":`Tekrar verdi`,"Paid back in":`Geri dönüş`,"Nobody made a first payment in this period yet.":`Bu dönemde henüz ilk ödemesini yapan olmadı.`,"nobody new":`yeni kişi yok`,"%d days":`%d gün`,"not yet":`henüz değil`,"A person belongs to the campaign of their first payment. Their later payments count for that campaign even when they came back without an ad. CAC is the campaign spend in this period divided by the new people it brought.":`Bir kişi, ilk ödemesinin kampanyasına aittir. Sonraki ödemeleri, reklamsız geri gelse bile o kampanyaya sayılır. CAC, bu dönemdeki kampanya harcamasının getirdiği yeni kişi sayısına bölünmesidir.`,"Value by month of first payment":`İlk ödeme ayına göre değer`,"Each row is the people who paid for the first time that month. The cells show what one person gave in total by the end of each month since then.":`Her satır o ay ilk kez ödeme yapan kişiler. Hücreler, o günden beri her ayın sonunda bir kişinin toplam ne verdiğini gösterir.`,Month:`Ay`,People:`Kişi`,"M%d":`A%d`,"Sent again. The row shows the result.":`Yeniden gönderildi. Sonuç satırda görünür.`,"visitor did not accept cookies":`ziyaretçi çerezleri kabul etmedi`,"already sent from the browser":`tarayıcıdan zaten gönderildi`,"platform turned off":`platform kapatıldı`,"order deleted":`sipariş silindi`,Sent:`Gönderildi`,Waiting:`Bekliyor`,Failed:`Başarısız`,"Not sent":`Gönderilmedi`,"no consent, or sent from the browser":`onay yok ya da tarayıcıdan gitti`,Platform:`Platform`,Value:`Değer`,Status:`Durum`,"Nothing sent yet. When a donation is paid, a Purchase event is sent to every platform that has its server key.":`Henüz gönderim yok. Bir bağış ödenince, sunucu anahtarı girilmiş her platforma Purchase olayı gider.`,"%d attempts":`%d deneme`,"Send again":`Yeniden gönder`,Copied:`Kopyalandı`,"Tag each ad with its own link":`Her reklamı kendi bağlantısıyla etiketleyin`,'Meta, Google and TikTok add their click ID by themselves. A UTM link also names the campaign and the ad, so the report can show "which ad brought which donation". Paste the link as the ad\'s website URL; use a different "Ad" value for each ad or video.':`Meta, Google ve TikTok tıklama kimliğini kendileri ekler. UTM bağlantısı kampanyayı ve reklamı da adlandırır; böylece rapor "hangi reklam hangi bağışı getirdi" gösterebilir. Bağlantıyı reklamın web sitesi adresine yapıştırın; her reklam ya da video için farklı bir "Reklam" değeri kullanın.`,Page:`Sayfa`,Type:`Tür`,Copy:`Kopyala`,"Meta tip: instead of one link per ad you can put this in the ad's URL parameters field: utm_source={{site_source_name}}&utm_medium=paid_social&utm_campaign={{campaign.name}}&utm_content={{ad.name}}":`Meta ipucu: her reklama ayrı bağlantı yerine reklamın URL parametreleri alanına şunu yazabilirsiniz: utm_source={{site_source_name}}&utm_medium=paid_social&utm_campaign={{campaign.name}}&utm_content={{ad.name}}`,"Settings saved.":`Ayarlar kaydedildi.`,"You are not allowed to do this.":`Bunu yapmaya yetkiniz yok.`,"Set in wp-config.php":`wp-config.php'de tanımlı`,Remove:`Kaldır`,Undo:`Geri al`,On:`Açık`,"Test the connection":`Bağlantıyı test et`,"Pixel (dataset) ID":`Pixel (veri kümesi) kimliği`,"Events Manager › Data sources › your pixel › Settings.":`Olay Yöneticisi › Veri kaynakları › pixel'iniz › Ayarlar.`,"Conversions API access token":`Conversions API erişim anahtarı`,"Events Manager › Settings › Conversions API › Generate access token. Needed for server events (bank transfers, ad blockers).":`Olay Yöneticisi › Ayarlar › Conversions API › Erişim anahtarı oluştur. Sunucu olayları için gerekli (Havale/EFT, reklam engelleyiciler).`,"Test event code (optional)":`Test olay kodu (isteğe bağlı)`,"While testing only. Empty it after testing, or real donations are reported as test events.":`Yalnız test sırasında. Testten sonra boşaltın; yoksa gerçek bağışlar test olayı olarak gider.`,"Ad spend (for ROAS)":`Reklam harcaması (ROAS için)`,"Ad account ID":`Reklam hesabı kimliği`,"Ads Manager › account menu at the top left, the number under the account name (act_ is optional).":`Reklam Yöneticisi › sol üstteki hesap menüsü, hesap adının altındaki sayı (act_ yazmak gerekmez).`,"Facebook Page ID":`Facebook sayfa kimliği`,"The page Studio ads are published as. Page › About › Page transparency › Page ID.":`Stüdyo reklamlarının adına yayınlanacağı sayfa. Sayfa › Hakkında › Sayfa şeffaflığı › Sayfa kimliği.`,"Marketing API token":`Marketing API anahtarı`,"Business Settings › Users › System users › add the ad account › Generate token. ads_read is enough for spend; audiences, Campaigns changes and Studio drafts need ads_management. Empty = the Conversions API token is tried. Flux Ads changes your ad account only when you approve it: an audience, a pause or budget change, or a Studio draft (always created paused).":`İşletme Ayarları › Kullanıcılar › Sistem kullanıcıları › reklam hesabını ekleyin › Belirteç oluştur. Harcama için ads_read yeter; kitleler, Kampanyalar değişiklikleri ve Stüdyo taslakları ads_management ister. Boşsa Conversions API anahtarı denenir. Flux Ads reklam hesabınızı yalnız siz onaylayınca değiştirir: kitle, duraklatma ya da bütçe değişikliği veya Stüdyo taslağı (her zaman duraklatılmış oluşturulur).`,"Pixel ID":`Pixel kimliği`,"TikTok Ads Manager › Tools › Events › Web events.":`TikTok Ads Manager › Araçlar › Olaylar › Web olayları.`,"Events API access token":`Events API erişim anahtarı`,"Pixel › Settings › Events API › Generate access token.":`Pixel › Ayarlar › Events API › Erişim anahtarı oluştur.`,"While testing only.":`Yalnız test sırasında.`,"Measurement ID":`Ölçüm kimliği`,"Empty = the theme's ID (%s). The theme already loads the tag; Flux Ads only adds the donation events.":`Boş = temadaki kimlik (%s). Etiketi tema zaten yüklüyor; Flux Ads yalnız bağış olaylarını ekler.`,"Admin › Data streams › Measurement ID.":`Yönetici › Veri akışları › Ölçüm kimliği.`,"Measurement Protocol API secret":`Measurement Protocol API gizli anahtarı`,'Data stream › Measurement Protocol API secrets › Create. Needed for bank-transfer donations approved later. To see donations in Google Ads, import the GA4 "purchase" conversion there.':`Veri akışı › Measurement Protocol API gizli anahtarları › Oluştur. Sonradan onaylanan Havale/EFT bağışları için gerekli. Bağışları Google Ads'te görmek için GA4 "purchase" dönüşümünü orada içe aktarın.`,"Target ROAS":`Hedef ROAS`,"Income on the site per 1 spent on ads. Under half of it: lower the budget; 1.5 times and more: raise it.":`Reklama harcanan her 1 birim için sitedeki gelir. Yarısının altı: bütçeyi düşür; 1,5 katı ve üstü: artır.`,"Spend before judging (7 days)":`Değerlendirme için en az harcama (7 gün)`,"In the ad account currency. 0 = automatic: twice your average cost per payment.":`Reklam hesabının para biriminde. 0 = otomatik: ödeme başı ortalama maliyetin iki katı.`,Privacy:`Gizlilik`,"Cookie consent":`Çerez onayı`,"Wait for consent (recommended): pixels and the ad cookie start only after the visitor accepts the theme cookie banner. Donations of visitors who did not accept are counted in the report but not sent to ad platforms.":`Onayı bekle (önerilen): pixel'ler ve reklam çerezi yalnız ziyaretçi temanın çerez banner'ını kabul edince başlar. Kabul etmeyenlerin bağışı raporda sayılır ama reklam platformlarına gönderilmez.`,"Always: you collect consent another way.":`Her zaman: onayı başka bir yolla alıyorsunuz.`,"E-mail and phone (for better matching)":`E-posta ve telefon (daha iyi eşleşme için)`,"Only for contacts with ad consent in Flux CRM (recommended). Sent as SHA-256 hashes, never in plain text.":`Yalnız Flux CRM'de reklam izni olan kişilerde (önerilen). SHA-256 hash olarak gider, asla açık metin değil.`,"Never: only the browser ID, IP and browser type.":`Hiçbir zaman: yalnız tarayıcı kimliği, IP ve tarayıcı türü.`,"Always (hashed). Your privacy notice must say so.":`Her zaman (hash'li). Aydınlatma metninizde yazmalı.`,"Load the browser pixels too (page views, form and checkout steps). Off = server events only.":`Tarayıcı pixel'leri de yüklensin (sayfa görüntüleme, form ve ödeme adımları). Kapalı = yalnız sunucu olayları.`,"Attribution window (days)":`Atıf süresi (gün)`,"How long a click counts for a later donation.":`Bir tıklama sonraki bağış için kaç gün sayılır.`,"Save settings":`Ayarları kaydet`,"in %s day\0in %s days":`%s gün sonra\0%s gün sonra`,"Draft written. Read it and edit what you need.":`Taslak yazıldı. Oku ve gerekeni düzenle.`,"Draft saved.":`Taslak kaydedildi.`,"Draft deleted.":`Taslak silindi.`,"You can write drafts now. To send them to Meta, add: %s.":`Taslak yazabilirsiniz. Meta'ya göndermek için şunu ekleyin: %s.`,"Write a draft with AI":`AI ile taslak yaz`,"Flux AI is not ready. Install Flux AI & MCP and add a model key, or start from an empty draft.":`Flux AI hazır değil. Flux AI & MCP'yi kurup model anahtarı ekleyin ya da boş taslakla başlayın.`,Brief:`Brif`,"e.g. Sapling campaign for November; reach people like our donors in Istanbul and Ankara, leave out people who donated this month.":`ör. Kasım fidan kampanyası; İstanbul ve Ankara'da bağışçılarımıza benzeyenlere ulaş, bu ay bağış yapanları dışarıda bırak.`,"Page the ads open":`Reklamların açacağı sayfa`,Goal:`Amaç`,"Writing…":`Yazılıyor…`,"Write draft":`Taslak yaz`,"Empty draft":`Boş taslak`,Drafts:`Taslaklar`,"Ad sets / ads":`Reklam seti / reklam`,Updated:`Güncellendi`,"No drafts yet.":`Henüz taslak yok.`,"Open in Campaigns":`Kampanyalar'da aç`,Duplicate:`Kopyala`,"Only the draft here is deleted. The paused campaign stays in Meta.":`Yalnız buradaki taslak silinir. Duraklatılmış kampanya Meta'da kalır.`,"The draft is deleted.":`Taslak silinir.`,"The campaign is in Meta, paused. Turn it on under Campaigns when you are ready.":`Kampanya Meta'da, duraklatılmış durumda. Hazır olunca Kampanyalar'dan aç.`,"All drafts":`Tüm taslaklar`,"Draft not found.":`Taslak bulunamadı.`,"This draft is in Meta as a paused campaign. Turn it on or change it under Campaigns; to try a new version, duplicate it.":`Bu taslak Meta'da duraklatılmış kampanya olarak duruyor. Kampanyalar'dan açın ya da değiştirin; yeni bir sürüm denemek için kopyalayın.`,"Why this plan (AI)":`Neden bu plan (AI)`,Name:`Ad`,"Ad sets (who sees it)":`Reklam setleri (kimler görür)`,"Ad set name":`Reklam seti adı`,Ages:`Yaş`,Gender:`Cinsiyet`,"all genders":`tüm cinsiyetler`,women:`kadın`,men:`erkek`,"Countries (ISO, comma)":`Ülkeler (ISO, virgülle)`,"Budget share %":`Bütçe payı %`,"Show to audiences":`Gösterilecek kitleler`,"Leave out audiences":`Hariç tutulacak kitleler`,"Add ad set":`Reklam seti ekle`,"Ads (text variants)":`Reklamlar (metin çeşitleri)`,"Each variant runs in every ad set, so Meta can find the text that works best.":`Her çeşit her reklam setinde çalışır; Meta en iyi işleyen metni böylece bulur.`,"Variant name":`Çeşit adı`,"Primary text":`Ana metin`,Headline:`Başlık`,Description:`Açıklama`,Button:`Düğme`,"Image address (optional)":`Görsel adresi (isteğe bağlı)`,"Add variant":`Çeşit ekle`,"Save draft":`Taslağı kaydet`,"Send to Meta":`Meta'ya gönder`,"Missing: %s.":`Eksik: %s.`,"Save your edits first. Ads open the page with UTM tags, so donations show up in the report and under Campaigns.":`Önce değişikliklerinizi kaydedin. Reklamlar sayfayı UTM etiketleriyle açar; bağışlar raporda ve Kampanyalar'da görünür.`,"A paused campaign with %1$d ad sets and %2$d ads is created in Meta. Nothing is shown or spent until you turn it on under Campaigns.":`Meta'da %1$d reklam setli, %2$d reklamlı duraklatılmış bir kampanya oluşturulur. Kampanyalar'dan açana kadar hiçbir şey gösterilmez, harcanmaz.`,"Create paused":`Duraklatılmış oluştur`,"Create in Meta (paused)":`Meta'da oluştur (duraklatılmış)`,"Date saved.":`Tarih kaydedildi.`,"Date deleted.":`Tarih silindi.`,running:`sürüyor`,"approximate; check the official calendar":`tahmini; resmi takvimden kontrol edin`,"Last year: %1$s payments, %2$s, %3$s new donors.":`Geçen yıl: %1$s ödeme, %2$s, %3$s yeni bağışçı.`,"Ad spend %1$s (ROAS %2$s).":`Reklam harcaması %1$s (ROAS %2$s).`,"No payments in this period last year.":`Geçen yıl bu dönemde ödeme yok.`,"Delete this date?":`Bu tarih silinsin mi?`,"Add your own date":`Kendi tarihinizi ekleyin`,"A campaign day of your own: an anniversary, an event, a planting day.":`Size özel bir kampanya günü: yıldönümü, etkinlik, dikim günü.`,"Prepare days before":`Kaç gün önce hazırlan`,Add:`Ekle`,"Audience created in Meta and filled.":`Kitle Meta'da oluşturuldu ve dolduruldu.`,"Lookalike audience created. Meta fills it within a few hours.":`Benzer kitle oluşturuldu. Meta birkaç saat içinde doldurur.`,"Audience updated.":`Kitle güncellendi.`,"Audience deleted.":`Kitle silindi.`,"Audiences need Flux CRM: people, ad consent and segments come from there.":`Kitleler için Flux CRM gerekli: kişiler, reklam izni ve segmentler oradan gelir.`,"Enter the Meta ad account ID and a Marketing API key with the ads_management permission in Settings › Meta.":`Ayarlar › Meta'da reklam hesabı kimliğini ve ads_management izinli bir Marketing API anahtarını girin.`,Group:`Grup`,Use:`Kullanım`,"No audience yet.":`Henüz kitle yok.`,"Meta fills it":`Meta doldurur`,"%1$s · +%2$d / −%3$d":`%1$s · +%2$d / −%3$d`,"The audience is deleted in Meta too. Ad sets that use it stop reaching these people.":`Kitle Meta'da da silinir. Onu kullanan reklam setleri bu kişilere ulaşmayı bırakır.`,"New audience":`Yeni kitle`,"Name in Meta":`Meta'daki adı`,"Donors – last 12 months":`Bağışçılar – son 12 ay`,"%s people":`%s kişi`,"Also create a lookalike audience (people similar to this group)":`Benzer kitle de oluştur (bu gruba benzeyen kişiler)`,"Lookalike country":`Benzer kitle ülkesi`,"Lookalike size":`Benzer kitle büyüklüğü`,"%d%% of the country":`Ülkenin %%%d'i`,"Create in Meta":`Meta'da oluştur`,"Meta needs at least 100 matched people for a lookalike. 1% is the closest match; larger sizes reach more people with less similarity.":`Benzer kitle için Meta'nın en az 100 eşleşen kişiye ihtiyacı var. %1 en yakın benzerlik; büyüdükçe daha çok kişiye, daha az benzerlikle ulaşır.`,"Lookalike from an existing audience":`Mevcut kitleden benzer kitle`,"Source audience":`Kaynak kitle`,"Create lookalike":`Benzer kitle oluştur`,'Flux AI writes a campaign draft from your brief and this site\'s numbers: ad sets, audiences, budget split and ad text variants. You read and edit it here. "Send to Meta" creates everything paused; nothing is shown or spent until you turn it on under Campaigns.':`Flux AI, brifinizden ve bu sitenin rakamlarından bir kampanya taslağı yazar: reklam setleri, kitleler, bütçe dağılımı ve reklam metni çeşitleri. Burada okuyup düzenlersiniz. "Meta'ya gönder" her şeyi duraklatılmış oluşturur; Kampanyalar'dan açana kadar hiçbir şey gösterilmez, harcanmaz.`,'The periods when giving peaks, with what the same period brought last year. Start the campaign before the period: Meta needs a few days to review and learn. "Write a draft" opens Studio with the brief and dates filled in; nothing goes to Meta from here.':`Bağışların yükseldiği dönemler ve geçen yıl aynı dönemin getirdikleri. Kampanyayı dönemden önce başlatın: Meta'nın inceleyip öğrenmesi birkaç gün sürer. "Taslak yaz" Stüdyo'yu brif ve tarihler dolu açar; buradan Meta'ya hiçbir şey gitmez.`,"Send a group of people from Flux CRM to Meta as an audience: to show ads to similar people, or to stop showing ads to people who just donated. Only people who gave ad consent are sent, as encrypted (hashed) email and phone. The list is updated every day; someone who withdraws consent is removed straight away.":`Flux CRM'deki bir kişi grubunu Meta'ya kitle olarak gönderin: benzer kişilere reklam göstermek ya da yeni bağış yapanlara reklam göstermemek için. Yalnız reklam izni veren kişiler, şifrelenmiş (özetlenmiş) e-posta ve telefonla gider. Liste her gün güncellenir; iznini geri alan kişi hemen çıkarılır.`,"Last 7 days":`Son 7 gün`,"Last 30 days":`Son 30 gün`,"Last 90 days":`Son 90 gün`,"Last 12 months":`Son 12 ay`,Custom:`Özel`,From:`Başlangıç`,To:`Bitiş`,Show:`Göster`,"Donations and orders":`Bağış ve siparişler`,Donations:`Bağışlar`,"Shop orders":`Mağaza siparişleri`,"Group by":`Grupla`},de:{},es:{},fr:{},"pt-br":{},ja:{},zh:{},ar:{},ru:{}};function Te(e,t){let n=0;return e.replace(/%%|%(?:(\d+)\$)?[sd]/g,(e,r)=>e===`%%`?`%`:String(t[r?Number(r)-1:n++]??``))}function Ee(e)